import {escapeHTML as e} from '/model.mjs';
const app=document.querySelector('#tickets');
let token=new URLSearchParams(location.hash.slice(1)).get('receipt');
history.replaceState(null,'',location.pathname);
async function load(){
  if(!token){app.innerHTML='<h1>Your fight-night tickets.</h1><div class="panel"><p>Open the private ticket link in your booking email to view your QR codes.</p><a class="button" href="/events/">View fight nights</a></div>';return;}
  const response=await fetch('/api/ticket/receipt',{method:'POST',credentials:'omit',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({token}),signal:AbortSignal.timeout(18000)});
  const order=await response.json();if(!response.ok)throw Error(order.error||'Your tickets are not available yet.');
  app.innerHTML=`<h1>Your night. Your corner.</h1><p class="intro">Print your QR ticket or show it on your phone. Bring ID matching the name on your ticket. Keep your QR and ticket link private.</p>${order.eventStatus!=='scheduled'?`<div class="banner">Event status: ${e(order.eventStatus)}. Check the organiser’s latest update before travelling.</div>`:''}<div class="actions"><button id="print">Print / save as PDF</button><button id="reload">Refresh ticket status</button></div>${order.tickets.map(ticket=>`<article class="ticket"><div><div class="label">SOHAIB MOHAMMED · DIGITAL ADMISSION</div><h2>${e(order.event)}</h2><p>${e(new Date(order.startsAt).toLocaleString('en-GB',{dateStyle:'full',timeStyle:'short',timeZone:'Europe/London'}))}<br>${e(order.venue)}</p><div class="label">ATTENDEE · BRING MATCHING ID</div><div class="name">${e(ticket.name)}</div><p>${e(ticket.category)}</p>${ticket.status!=='valid'?`<div class="status">${e(ticket.status==='used'?'Already admitted':ticket.status==='revoked'?'Revoked · contact the organiser':ticket.status)}</div>`:''}<div class="reference">ORDER ${e(order.reference)}<br>TICKET ${e(ticket.id)}</div></div><div class="qr-wrap">${ticket.status==='valid'?`<img class="qr" src="${e(ticket.qr)}" alt="Unique admission QR for ${e(ticket.name)}"><div class="token">${e(ticket.token)}</div>`:'<p class="status">This admission is no longer valid for entry.</p>'}</div></article>`).join('')}`;
  document.querySelector('#print').onclick=()=>window.print();document.querySelector('#reload').onclick=()=>load().catch(showError);
}
function showError(error){app.innerHTML=`<h1>Let’s check your tickets.</h1><section class="panel"><p class="message">${e(error.message||'Connection unavailable. Try again.')}</p><p>If you have just paid, payment confirmation may still be arriving. Keep this page open and try again shortly.</p><button id="retry">Check again</button></section>`;document.querySelector('#retry').onclick=()=>load().catch(showError);}
load().catch(showError);
